liquid:
{%- assign valid = true -%}
{%- assign matches = false -%}
{%- assign inputs = nil -%}
{%- assign hasInputs = apiEaseParameters | has_key: 'liquidParams' -%}
{%- if hasInputs -%}
  {%- assign inputs = apiEaseParameters.liquidParams -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs | has_key: 'candidateSku' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs.candidateSku | is_type: 'string' -%}
  {%- assign isNull = inputs.candidateSku | is_type: 'null' -%}
  {%- if isNull -%}{%- assign valid = true -%}{%- endif -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs | has_key: 'expectedSku' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs.expectedSku | is_type: 'string' -%}
{%- endif -%}
{%- if valid -%}
  {%- if inputs.expectedSku == '' -%}{%- assign valid = false -%}{%- endif -%}
{%- endif -%}
{%- if valid -%}
  {%- if inputs.candidateSku == inputs.expectedSku -%}{%- assign matches = true -%}{%- endif -%}
{%- endif -%}
{%- if valid -%}
{"success":true,"matches":{{ matches | json }},"error":null}
{%- else -%}
{"success":false,"matches":false,"error":"candidateSku must be present as a string or null; expectedSku must be a present nonempty string."}
{%- endif -%}
